lib = '''def most_common(grid):
    """The most frequent cell color in the grid (the usual background)."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def tile_unit(grid, unit):
    """The grid rebuilt by tiling the given block of rows (list of rows) over the full height and width."""
    uh, uw = len(unit), len(unit[0])
    return [[unit[i % uh][j % uw] for j in range(len(grid[0]))] for i in range(len(grid))]

def transpose(grid):
    """The grid reflected over its main diagonal."""
    return [list(r) for r in zip(*grid)]

def frontier_line(grid, horizontal=False):
    """Index of the first full line (row, or column if horizontal) of one non-background color, else None."""
    bg = most_common(grid)
    if horizontal:
        return next((j for j in range(len(grid[0])) if len({r[j] for r in grid}) == 1 and grid[0][j] != bg), None)
    return next((i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg), None)

def unit_from_repeats(grid):
    """The block of rows ending at the last repeat of a non-background row, with length the repeat gap."""
    bg = most_common(grid)
    rows = [tuple(r) for r in grid]
    distinctive = [i for i, r in enumerate(rows) if any(v != bg for v in r)]
    for i in distinctive:
        for j in distinctive:
            if i < j and rows[i] == rows[j]:
                per = j - i
                last = max(k for k in distinctive if rows[k] == rows[j])
                return [list(rows[k]) for k in range(last - per + 1, last + 1)]
    return grid
'''
